SELECT COUNT(DISTINCT s.zoneref) 
FROM scans s 
WHERE EXISTS (SELECT 1 FROM scanpointcloud sp WHERE sp.arcref = s.arcref);

-- Check if there's a 1:1 relationship between scans and scanpointcloud via arcref when using DISTINCT
SELECT COUNT(DISTINCT sp.arcref) FROM scanpointcloud sp 
JOIN scans s ON sp.arcref = s.arcref;
